import {evaluate,remaining,expandRange,key} from './engine.js';
import {scenarios,topics} from './scenarios.js';
const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',book:'<path d="M12 5c-3-2-6-2-9-1v15c3-1 6-1 9 1 3-2 6-2 9-1V4c-3-1-6-1-9 1Zm0 0v15"/>',repeat:'<path d="M20 8a8 8 0 0 0-14-3L3 8m0-5v5h5M4 16a8 8 0 0 0 14 3l3-3m0 5v-5h-5"/>',chart:'<path d="M4 20V10m8 10V4m8 16v-7"/>',bolt:'<path d="m13 2-9 12h7l-1 8 10-12h-7l1-8Z"/>',bulb:'<path d="M9 18h6m-5 3h4M8 14a7 7 0 1 1 8 0l-1 2H9Z"/>',shuffle:'<path d="M3 5h3c4 0 8 14 12 14h3M3 19h3c2 0 4-4 6-7s4-7 6-7h3m-4-4 4 4-4 4m0 6 4 4-4 4"/>',check:'<path d="m5 12 4 4L19 6"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9.5 9a2.5 2.5 0 1 1 4 2c-1 .5-1.5 1-1.5 2m0 3v.5"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>'};
const icon=name=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.grid}</svg>`;
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const symbols={s:'♠',h:'♥',d:'♦',c:'♣'};
const suitNames={s:'spades',h:'hearts',d:'diamonds',c:'clubs'};
const rankNames={T:'10',J:'jack',Q:'queen',K:'king',A:'ace'};
const cardName=c=>`${rankNames[c[0]]||c[0]} of ${suitNames[c[1]]}`;
const card=(c,small=false)=>c?`<div class="playing-card ${/[hd]/.test(c[1])?'red':''} ${small?'small':''}" role="img" aria-label="${cardName(c)}"><span class="rank">${c[0]==='T'?'10':c[0]}</span><span class="suit">${symbols[c[1]]}</span><span class="corner">${symbols[c[1]]}</span></div>`:'<div class="playing-card empty" role="img" aria-label="Unrevealed board card">·</div>';
const inlineCard=c=>`<span class="${/[hd]/.test(c[1])?'mini-red':''}" aria-label="${cardName(c)}">${c[0]==='T'?'10':c[0]}${symbols[c[1]]}</span>`;
const combo=c=>c.map(inlineCard).join(' ');
const handLabel=t=>t.length===4?combo([t.slice(0,2),t.slice(2)]):t;
const STORAGE='combo-lab-progress-v1';
let storageOK=true;
function load(){try{const d=JSON.parse(localStorage.getItem(STORAGE));if(d?.version===1&&Array.isArray(d.attempts)&&d.records&&typeof d.records==='object'){return d}}catch{}return {version:1,attempts:[],records:{}}}
let progress=load();
let state={view:'train',topic:'all',level:'all',index:0,order:scenarios.map(s=>s.id),answer:'',result:null,hinted:false,showHint:false,shuffle:false,round:1,error:'',confirmReset:false};
function save(){try{localStorage.setItem(STORAGE,JSON.stringify(progress))}catch{storageOK=false}}
function filtered(){return state.order.map(id=>scenarios.find(s=>s.id===id)).filter(s=>s&&(state.topic==='all'||s.topic===state.topic)&&(state.level==='all'||s.level===state.level));}
function queue(){return scenarios.filter(s=>progress.records[s.id]?.review)}
function pool(){return state.view==='review'?queue():filtered()}
let reviewCurrent=null;
function current(){if(state.view==='review')return reviewCurrent||queue()[0];const p=filtered();return p[state.index%Math.max(p.length,1)]}
function resetQuestion(){state.answer='';state.result=null;state.hinted=false;state.showHint=false;state.error=''}
function stats(){const a=progress.attempts;const unaided=a.filter(x=>x.correct&&!x.hinted&&!x.revealed);let streak=0;for(let i=a.length-1;i>=0;i--){if(a[i].correct&&!a[i].hinted&&!a[i].revealed)streak++;else break}return{total:a.length,correct:unaided.length,accuracy:a.length?Math.round(unaided.length/a.length*100):0,streak,mastered:scenarios.filter(s=>progress.records[s.id]?.mastered).length}}
function nav(view){state.view=view;state.confirmReset=false;resetQuestion();reviewCurrent=view==='review'?queue()[0]:null;render();window.scrollTo({top:0,behavior:'instant'})}
function submit(reveal=false){
 const s=current();if(!s||state.result)return;
 const answer=state.answer.trim();
 if(!reveal&&(!/^\d+$/.test(answer)||!Number.isSafeInteger(Number(answer)))){state.error='Enter a whole number, including 0 if no combos remain.';render();document.querySelector('#answer')?.focus();return}
 const e=evaluate(s),correct=!reveal&&Number(answer)===e.answer;
 state.result={correct,revealed:reveal,entered:reveal?null:Number(answer),...e};
 const clean=correct&&!state.hinted&&!reveal;
 const old=progress.records[s.id]||{};
 progress.records[s.id]={attempts:(old.attempts||0)+1,correct:(old.correct||0)+(correct?1:0),review:!clean,mastered:clean,lastResult:clean?'correct':reveal?'revealed':correct?'hinted':'missed'};
 progress.attempts.push({id:s.id,correct,hinted:state.hinted,revealed:reveal,at:new Date().toISOString()});
 progress.attempts=progress.attempts.slice(-2000);save();render();document.querySelector('#feedback')?.focus({preventScroll:true})
}
function next(){
 resetQuestion();if(state.view==='review'){const q=queue();const i=q.findIndex(x=>x.id===reviewCurrent?.id);reviewCurrent=q.length?q[(i+1)%q.length]:null;}
 else{state.index++;if(state.index>=filtered().length){state.index=0;state.round++;}}
 render();document.querySelector('#answer')?.focus({preventScroll:true});if(window.innerWidth<780)document.querySelector('.hand-panel')?.scrollIntoView({behavior:'smooth',block:'start'})
}
function changeTopic(topic){state.topic=topic;state.index=0;state.round=1;resetQuestion();render()}
function shuffle(){state.shuffle=!state.shuffle;state.order=state.shuffle?[...scenarios].sort(()=>Math.random()-.5).map(s=>s.id):scenarios.map(s=>s.id);state.index=0;state.round=1;resetQuestion();render()}
function render(){
 const st=stats();const view=state.view;const title={train:'Practice',lessons:'Field guide',review:'Mistake review',progress:'Your progress'}[view];
 document.querySelector('#app').innerHTML=`<div class="layout"><aside class="sidebar"><div class="brand"><span class="brand-mark" aria-hidden="true">◈</span><div class="brand-name">COMBO <span>LAB</span></div></div><div class="side-label">Your study room</div><nav class="nav" aria-label="Main navigation">${[['train','grid','Practice'],['lessons','book','Field guide'],['review','repeat','Mistake review'],['progress','chart','Your progress']].map(([v,i,l])=>`<button data-nav="${v}" class="${view===v?'active':''}" ${view===v?'aria-current="page"':''} aria-label="${l}">${icon(i)}<span class="nav-label">${l}</span>${v==='review'&&queue().length?`<span class="badge">${queue().length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="study-note"><b>A little practice. A clearer range.</b>Count the cards. Understand the removal. Build the instinct.</div><div class="profile"><span class="avatar">♠</span><span>Your poker notebook<small>50bb · No-limit hold’em</small></span></div></div></aside><div class="main-wrap"><header class="topbar"><div class="crumb">Study room <span class="slash">/</span> <strong>${title}</strong></div><div class="top-meta"><span class="streak">${icon('bolt')} ${st.streak} in a row</span><span>6-max cash</span></div></header><main id="main" class="main">${!storageOK?'<p class="alert">This browser could not save progress. You can keep practicing in this session.</p>':''}${view==='lessons'?lessonsView():view==='progress'?progressView():trainingView()}<footer class="footer"><span>Training ranges are explicit assumptions, not solver recommendations.</span><button data-nav="progress">Progress saved in this browser</button></footer></main></div></div>`;
 bind();
}
function trainingView(){
 const review=state.view==='review';const s=current();const list=pool();
 if(!s)return `<div class="empty-state"><div class="empty-icon">${icon('check')}</div><h1>${review?'A clean slate.':'No drills in this selection.'}</h1><p>${review?'No questions are waiting for review. Missed, revealed, and hint-assisted answers will appear here. Answer one correctly without help to clear it.':'Try another level or choose all concepts.'}</p><button class="primary" data-action="${review?'practice':'reset-filters'}">${review?'Keep practicing':'Show all drills'}</button></div>`;
 const qidx=review?scenarios.findIndex(x=>x.id===s.id)+1:state.index+1;
 const done=filtered().filter(x=>progress.records[x.id]?.mastered).length;
 return `<div class="title-row"><div><h1>${review?'Make it click.':'Count the range.'}</h1><p class="subtitle">${review?'Revisit the spots that need another look.':'One hand. One range. Every combination matters.'}</p></div><button class="outline-button" data-nav="lessons" aria-label="Quick reference">${icon('book')}<span class="button-label">Quick reference</span></button></div>${review?`<div class="review-callout">${queue().length} question${queue().length!==1?'s':''} left to revisit. An unaided correct answer clears a question.</div>`:`<div class="filters"><div class="segmented" aria-label="Concept focus">${Object.entries(topics).map(([k,v])=>`<button data-topic="${k}" class="${state.topic===k?'active':''}" aria-pressed="${state.topic===k}">${v}</button>`).join('')}</div><div class="filter-select"><label for="level">Level</label><select id="level">${['all','Foundations','Applied','Advanced'].map(v=>`<option value="${v}" ${state.level===v?'selected':''}>${v==='all'?'All levels':v}</option>`).join('')}</select><button class="outline-button" data-action="shuffle" aria-label="Shuffle practice order" aria-pressed="${state.shuffle}" title="${state.shuffle?'Return to guided order':'Shuffle practice order'}">${icon('shuffle')}</button></div></div>`}${state.round>1&&!review?`<div class="fresh-round">Round ${state.round}. Repetition builds fluency — see how much you remember.</div>`:''}<div class="training-grid"><section class="hand-panel" aria-label="Hand scenario"><div class="hand-top"><div class="hand-title"><span class="small-pill">${s.street[0].toUpperCase()+s.street.slice(1)}</span>${review?'Review hand':`Hand ${String(qidx).padStart(2,'0')}`}</div><span class="muted">50bb starting stacks</span></div><div class="table-scene"><div class="poker-table"></div><div class="table-watermark" aria-hidden="true">COMBO LAB</div><div class="seat villain-seat"><div class="mini-backs" aria-hidden="true"><span class="card-back"></span><span class="card-back"></span></div><span class="seat-label"><b>Villain</b><span>· ${s.villainPosition}</span></span></div><div class="dealer ${s.heroPosition==='BTN'?'hero-dealer':s.villainPosition==='BTN'?'':'off-table'}" title="Dealer button">D</div><div class="board-wrap"><div class="pot">Pot after villain’s bet <b>${s.potAfterBet}bb</b></div><div class="board" aria-label="Community cards">${[0,1,2,3,4].map(i=>card(s.board[i])).join('')}</div></div><div class="seat hero-seat"><div class="hero-cards" aria-label="Your hole cards">${s.hero.map(c=>card(c,true)).join('')}</div><span class="seat-label"><b>You</b><span>· ${s.heroPosition}</span></span></div></div><div class="scene-meta"><span>Position <b>${s.heroPosition} vs ${s.villainPosition}</b></span><span>Single-raised pot</span><span>No rake</span></div><div class="history"><div class="section-row"><h3>Action leading here</h3><span class="eyebrow">${s.street==='preflop'?'Preflop':s.street==='river'?'4 streets':s.street==='turn'?'3 streets':'2 streets'}</span></div><div class="history-list">${s.history.map(([street,text],i)=>`<div class="history-step ${i===s.history.length-1?'current':''}"><span class="dot" aria-hidden="true"></span><span class="street">${street}</span><p>${text}</p></div>`).join('')}</div></div></section><section class="answer-panel" aria-label="Combo question"><div class="answer-kicker"><span class="eyebrow">${topics[s.topic]}</span><span>${s.level}</span></div><h2>${s.question}</h2><p class="question-sub">${s.kind==='blocked'?'Count the combinations removed by your hole cards, after accounting for the board.':'Account for the board and your hole cards. Count only the range below.'}</p><div class="range-box"><label>Villain’s assumed target range</label><div class="range-tags">${s.range.map(t=>`<span class="range-tag">${handLabel(t)}</span>`).join('')}</div><p class="range-note">Every listed combo is included at 100%. This may be only part of villain’s range.</p></div>${state.result?feedback(s):`<form id="answer-form"><label class="answer-label" for="answer">Your count</label><div class="number-wrap"><input id="answer" type="text" inputmode="numeric" pattern="[0-9]*" autocomplete="off" placeholder="0" value="${escape(state.answer)}" aria-describedby="${state.error?'answer-error':'input-help'}" ${state.error?'aria-invalid="true"':''}><span>combos</span></div>${state.error?`<p class="formula-note storage-note" id="answer-error" role="alert">${state.error}</p>`:''}<button class="primary" type="submit">Check answer <span class="key-tag" aria-hidden="true">↵</span></button></form><div class="answer-actions"><button class="text-button" data-action="hint">${icon('bulb')}${state.showHint?'Hide hint':'Give me a hint'}</button><button class="text-button" data-action="reveal">Show solution</button></div>${state.showHint?`<div class="hint" role="status">${s.hint}</div>`:''}<p id="input-help" class="small-info">Take your time. Accuracy first, speed later.<br>A combo is one specific two-card hand.</p>`}</section></div>${state.result?breakdown(s):''}<div class="bottom-grid"><div class="reference-card"><div class="reference-icon">${icon('bulb')}</div><div><h3>${s.topic==='counting'?'Count what is actually available.':s.topic==='blockers'?'A blocker always has a target.':'Unblocking means leaving hands available.'}</h3><p>${s.topic==='counting'?'Start with the range. Remove visible cards. Count each unique pair once.':s.topic==='blockers'?'Ask which part of villain’s range your exact cards remove.':"When bluff-catching, leaving villain’s possible bluffs intact can matter."}</p></div></div><div class="session-card"><div class="section-row"><h3>Your practice path</h3><b>${done} / ${filtered().length}</b></div><div class="progress-track" role="progressbar" aria-label="Mastered questions" aria-valuenow="${done}" aria-valuemin="0" aria-valuemax="${filtered().length}"><span style="width:${filtered().length?done/filtered().length*100:0}%"></span></div><p>Unique drills answered correctly without help</p></div></div>`;
}
function feedback(s){const r=state.result;return `<div class="feedback ${r.correct?'':'wrong'}" id="feedback" role="status" tabindex="-1"><div class="feedback-title">${r.revealed?'Let’s work it through.':r.correct?(state.hinted?'Correct — with a little help.':'Exactly right.'):'A useful spot to revisit.'}</div><div class="feedback-number">${r.answer} ${s.kind==='blocked'?'blocked':'remaining'} combo${r.answer===1?'':'s'}</div><p>${!r.correct&&!r.revealed?`Your answer was ${r.entered}. `:''}${s.lesson}</p></div><div class="math-strip"><div><b>${r.all.length}</b><small>Full range</small></div><span>›</span><div><b>${r.board.length}</b><small>After board</small></div><span>›</span><div class="live-count"><b>${r.live.length}</b><small>After your hand</small></div></div>${s.kind==='blocked'?`<p class="formula-note">${r.board.length} after board − ${r.live.length} remaining = <strong>${r.blocked.length} blocked by you</strong>.</p>`:''}<button class="primary" data-action="next">${state.view==='review'&&queue().length===0?'Finish review':'Next hand'}</button><p class="small-info">${r.correct&&!state.hinted?'Saved as an unaided correct answer.':'Added to mistake review. An unaided correct answer will clear it.'} See the exact combinations below.</p>`}
function breakdown(s){const e=state.result;return `<section class="breakdown" aria-label="Solution breakdown"><div class="breakdown-header"><div><h2>Make every combo visible.</h2><p class="subtitle">${s.title}</p></div><span class="small-pill">${e.blocked.length} removed by your hand</span></div><table class="range-table"><caption class="skip-link">Combination counts at each removal step</caption><thead><tr><th scope="col">Hand</th><th scope="col">Full range</th><th scope="col">After board</th><th scope="col">After your hand</th></tr></thead><tbody>${s.range.map(t=>`<tr><td>${handLabel(t)}</td><td>${expandRange([t]).length}</td><td>${remaining([t],s.board).length}</td><td>${remaining([t],[...s.board,...s.hero]).length}</td></tr>`).join('')}<tr><td><strong>Unique total</strong></td><td>${e.all.length}</td><td>${e.board.length}</td><td><strong>${e.live.length}</strong></td></tr></tbody></table><h3>Available to villain · ${e.live.length}</h3>${e.live.length?`<div class="combo-grid">${e.live.map(c=>`<span class="combo-chip">${combo(c)}</span>`).join('')}</div>`:'<p class="formula-note">None. Every listed combination contains a visible card.</p>'}<details ${e.blocked.length&&e.blocked.length<=8?'open':''}><summary>Removed by your hole cards · ${e.blocked.length}</summary>${e.blocked.length?`<div class="combo-grid">${e.blocked.map(c=>`<span class="combo-chip removed">${combo(c)}</span>`).join('')}</div>`:'<p class="formula-note">Your hand removes none of the board-legal combinations in this target range.</p>'}</details>${e.alternative?`<div class="hint"><strong>Change one card, change the range.</strong><p>With ${combo(s.alternative)} instead of ${combo(s.hero)}, <strong>${e.alternative.length}</strong> listed combos would remain instead of ${e.live.length}.</p>${s.comparison}</div>`:''}<p class="formula-note">Board cards and your cards are known dead cards. Villain cannot hold them. Folded hands are unknown, so we do not remove those cards.</p></section>`}
function lessonsView(){return `<div class="title-row"><div><h1>The range, made simple.</h1><p class="subtitle">A field guide to counting hands and understanding what your cards remove.</p></div></div><div class="lessons-grid"><article class="lesson-card"><div class="lesson-number">01 / COMBINATIONS</div><h2>Count physical hands.</h2><p>A combo is a specific pair of cards. A♠K♥ and A♠K♦ are different combos. A♠K♥ and K♥A♠ are the same combo.</p><div class="formula">6 · 4 · 12</div><p>With no visible cards: a pocket pair has <strong>6</strong> combos, a suited hand has <strong>4</strong>, and an offsuit hand has <strong>12</strong>.</p><ul><li>Pair: n × (n − 1) ÷ 2.</li><li>Unpaired ranks: available cards of rank A × available cards of rank B.</li><li>Suited: count intact same-suit pairs.</li><li>Offsuit: all rank combos − suited combos.</li></ul><button class="primary" data-start="counting">Practice counting</button></article><article class="lesson-card"><div class="lesson-number">02 / BLOCKERS</div><h2>Your cards remove hands.</h2><p>A blocker is a known card that makes some of villain’s combinations impossible. The suit can matter as much as the rank.</p><div class="formula">Before − after</div><p>To measure your blocker, compare the same board with and without your hole cards.</p><ul><li>Holding A♠ removes every villain combo containing A♠.</li><li>A queen of hearts does not remove a queen of spades.</li><li>A hand hit by two blockers is removed just once.</li></ul><button class="primary" data-start="blockers">Practice blockers</button></article><article class="lesson-card"><div class="lesson-number">03 / UNBLOCKERS</div><h2>Notice what you leave.</h2><p>You unblock a target range when your cards leave its combinations available. You are not adding hands to the deck.</p><div class="formula">Which range survives?</div><p>The desirable effect depends on the decision you are considering.</p><ul><li>Bluff-catching: blocking value and leaving bluffs available can help.</li><li>Bluffing: blocking calls and leaving folds available can help.</li><li>The exact assumed ranges and frequencies determine the effect.</li></ul><button class="primary" data-start="unblockers">Practice unblockers</button></article></div><article class="lesson-wide"><h2>Actions give context. Ranges make the count possible.</h2><p>A bet does not uniquely identify an opponent’s range. Each drill supplies a specific target range or subrange, with every listed combo included at 100%. Count that set exactly. The histories make the situation concrete; they are not solver outputs or betting recommendations.</p><p><strong>Read the notation:</strong> AK includes all suited and offsuit ace-king hands. AKs means suited; AKo means offsuit. Two cards with suit symbols, such as A♠K♠, mean that one exact combo. A blank board card has not been dealt yet.</p><p><strong>Raw counts versus frequencies:</strong> six possible combos played at 50% frequency contribute three effective combos. This trainer asks for raw, whole-number counts at 100% inclusion. Real decisions also depend on frequencies, bet size, equity, and the rest of the range.</p><p><strong>A useful routine:</strong> predict the answer, use a hint only if you need it, inspect the exact combinations, and revisit missed questions later. Explain why your hand removes each combo before moving on.</p><p class="formula-note">Further reading: <a href="https://blog.gtowizard.com/understanding-blockers-in-poker/" target="_blank" rel="noreferrer">GTO Wizard: Understanding Blockers</a> · <a href="https://blog.gtowizard.com/blockers-unblockers-the-secret-to-picking-great-bluffs/" target="_blank" rel="noreferrer">Blockers & Unblockers</a></p></article>`}
function progressView(){const st=stats();const recent=progress.attempts.slice(-10).reverse();return `<div class="title-row"><div><h1>Build the instinct.</h1><p class="subtitle">Focus on understanding first. Your results stay in this browser.</p></div><button class="outline-button" data-nav="train">Keep practicing</button></div><div class="stat-grid"><div class="stat"><b>${st.total}</b><span>Questions attempted</span></div><div class="stat"><b>${st.total?st.accuracy+'%':'—'}</b><span>Unaided accuracy</span></div><div class="stat"><b>${st.mastered} / ${scenarios.length}</b><span>Drills mastered</span></div><div class="stat"><b>${queue().length}</b><span>Questions to revisit</span></div></div><section class="progress-card"><h2>Understanding by concept</h2><p class="subtitle">A drill is mastered when your latest answer is correct without a hint or solution reveal.</p>${Object.entries(topics).filter(([k])=>k!=='all').map(([k,v])=>{const all=scenarios.filter(s=>s.topic===k),n=all.filter(s=>progress.records[s.id]?.mastered).length;return `<div class="topic-progress"><span>${v}</span><div class="progress-track" role="progressbar" aria-label="${v} mastery" aria-valuenow="${n}" aria-valuemin="0" aria-valuemax="${all.length}"><span style="width:${n/all.length*100}%"></span></div><span>${n} / ${all.length} drills</span></div>`}).join('')}<button class="outline-button" data-nav="review">${icon('repeat')} Review missed questions</button></section><section class="progress-card"><h2>Recent practice</h2>${recent.length?`<table class="range-table"><thead><tr><th scope="col">Drill</th><th scope="col">Result</th></tr></thead><tbody>${recent.map(r=>{const s=scenarios.find(s=>s.id===r.id);return `<tr><td>${escape(s?.title||r.id)}</td><td>${r.revealed?'Solution revealed':r.correct?r.hinted?'Correct with hint':'Correct':'Revisit'}</td></tr>`}).join('')}</tbody></table>`:'<p class="subtitle">Your first answer starts the story. Try a hand in Practice.</p>'}<p class="formula-note">Hints and solution reveals are practice, but do not count as unaided correct answers. Accuracy uses up to your latest 2,000 attempts. Progress is local to this browser; it does not sync across devices.</p><button class="text-button" data-action="reset-confirm">Reset local progress</button>${state.confirmReset?'<div class="reset-confirm"><span>Clear all attempts and your review queue?</span><button class="outline-button" data-action="reset">Clear progress</button><button class="text-button" data-action="cancel-reset">Cancel</button></div>':''}</section>`}
function bind(){
 document.querySelectorAll('[data-nav]').forEach(el=>el.onclick=()=>nav(el.dataset.nav));
 document.querySelectorAll('[data-topic]').forEach(el=>el.onclick=()=>changeTopic(el.dataset.topic));
 document.querySelectorAll('[data-start]').forEach(el=>el.onclick=()=>{state.topic=el.dataset.start;state.level='all';state.index=0;state.round=1;nav('train')});
 const level=document.querySelector('#level');if(level)level.onchange=()=>{state.level=level.value;state.index=0;resetQuestion();render()};
 const input=document.querySelector('#answer');if(input)input.oninput=()=>{state.answer=input.value;state.error=''};
 const form=document.querySelector('#answer-form');if(form)form.onsubmit=e=>{e.preventDefault();submit()};
 document.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>{switch(el.dataset.action){case'hint':state.hinted=true;state.showHint=!state.showHint;render();break;case'reveal':submit(true);break;case'next':next();break;case'shuffle':shuffle();break;case'practice':nav('train');break;case'reset-filters':state.topic='all';state.level='all';state.index=0;resetQuestion();render();break;case'reset-confirm':state.confirmReset=true;render();break;case'cancel-reset':state.confirmReset=false;render();break;case'reset':progress={version:1,attempts:[],records:{}};save();state.confirmReset=false;render();break;}})
}
render();
// Progressive enhancement: the same training journey for supported browser agents.
if(document.modelContext?.registerTool){
 const lifecycle=new AbortController();
 const readState=()=>{const s=current();return{view:state.view,topic:state.topic,level:state.level,question:s?{id:s.id,street:s.street,hero:s.hero,board:s.board,range:s.range,prompt:s.question}:null,result:state.result?{correct:state.result.correct,answer:state.result.answer}:null,progress:stats()}};
 const defs=[
 {name:'read_training_state',title:'Read current poker drill',description:'Read the current drill and progress. Does not reveal an unanswered solution.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:()=>readState()},
 {name:'start_practice',title:'Start poker practice',description:'Open practice with a selected concept and difficulty. Discards any unsubmitted answer.',inputSchema:{type:'object',properties:{topic:{type:'string',enum:Object.keys(topics)},level:{type:'string',enum:['all','Foundations','Applied','Advanced']}},required:['topic','level'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(!input||!Object.hasOwn(topics,input.topic)||!['all','Foundations','Applied','Advanced'].includes(input.level))throw new Error('Select a valid topic and level.');state.topic=input.topic;state.level=input.level;state.index=0;state.round=1;nav('train');return readState()}},
 {name:'submit_combo_count',title:'Submit combo answer',description:'Grade a whole-number combo count for the visible question and save the attempt to this browser’s progress.',inputSchema:{type:'object',properties:{count:{type:'integer',minimum:0}},required:['count'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(!input||!Number.isSafeInteger(input.count)||input.count<0)throw new Error('Count must be a nonnegative whole number.');if(!['train','review'].includes(state.view)||!current()||state.result)throw new Error('Open an unanswered practice question first.');state.answer=String(input.count);submit();return readState()}},
 {name:'next_practice_hand',title:'Continue to next poker hand',description:'Move to the next drill after the current question has been graded.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:()=>{if(!['train','review'].includes(state.view)||!state.result)throw new Error('Answer the current question first.');next();return readState()}}
 ];
 for(const def of defs){try{Promise.resolve(document.modelContext.registerTool(def,{signal:lifecycle.signal})).catch(()=>{})}catch{}}
 window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}
